 import unittest
from candidate import correct_bracketing

class TestCorrectBracketing(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(correct_bracketing(""))

    def test_single_opening_bracket(self):
        self.assertFalse(correct_bracketing("("))

    def test_single_closing_bracket(self):
        self.assertFalse(correct_bracketing(")"))

    def test_single_bracket(self):
        self.assertTrue(correct_bracketing(")("))

    def test_multiple_brackets_correct(self):
        self.assertTrue(correct_bracketing("(()())"))

    def test_multiple_brackets_incorrect_1(self):
        self.assertFalse(correct_bracketing(")(()"))

    def test_multiple_brackets_incorrect_2(self.test_multiple_brackets_incorrect_1):
        self.assertFalse(correct_bracketing(")()("))

    def test_multiple_brackets_incorrect_3(self):
        self.assertFalse(correct_bracketing("(())"))

    def test_multiple_brackets_incorrect_4(self):
        self.assertFalse(correct_bracketing("()("))

    def test_brackets_with_other_characters(self):
        self.assertFalse(correct_bracketing("a(bc)d"))

    def test_brackets_with_other_characters_correct(self):
        self.assertTrue(correct_bracketing("(a(bc)d)"))

if __name__ == '__main__':
    unittest.main()
